53	// countMembers returns how many entries belong to a group.
54	func countMembers(entries []browserRegistryEntry, slug string) int {
55		n := 0
56		for _, e := range entries {
57			if e.ParentSlug == slug {
58				n++
59			}
60		}
61		return n
62	}
