64	func (b *RegistryBrowser) cycleRegistryFilter() {
65		stops := b.filterStops()
66		if len(stops) == 0 {
67			b.registryFilter = resultFilter{}
68			b.rebuildTagTable()
69			return
70		}
71		if b.registryFilter.isEmpty() {
72			b.registryFilter = stops[0]
73			b.rebuildTagTable()
74			return
75		}
76		for i, s := range stops {
77			if s == b.registryFilter {
78				if i+1 < len(stops) {
79					b.registryFilter = stops[i+1]
80				} else {
81					b.registryFilter = resultFilter{} // back to everything
82				}
83				b.rebuildTagTable()
84				return
85			}
86		}
87		b.registryFilter = resultFilter{}
88		b.rebuildTagTable()
89	}
