78	func (b *RegistryBrowser) handleInputKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
79		switch msg.String() {
80		case "esc":
81			return b, func() tea.Msg { return RegistryBrowserCloseMsg{} }
82		case "down":
83			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
84			b.updateFocus()
85			return b, nil
86		case "up":
87			b.focusedField = max(b.focusedField-1, brFieldRepo)
88			b.updateFocus()
89			return b, nil
90		case " ":
91			if b.focusedField >= 1 && b.focusedField <= len(b.rows) {
92				row := b.rows[b.focusedField-1]
93				if row.groupSlug != "" {
94					b.toggleGroup(row.groupSlug)
95					return b, nil
96				}
97				key := b.entries[row.entry].key
98				b.selectedRegs[key] = !b.selectedRegs[key]
99				return b, nil
100			}
101		case "enter":
102			if b.focusedField == brFieldRepo || b.focusedField == b.brFieldSubmit() {
103				return b.submitSearch()
104			}
105			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
106			b.updateFocus()
107			return b, nil
108		}
109		return b.delegateUpdate(msg)
110	}
