9	// AddRegistryTags incorporates results from one registry into the combined tag list.
10	// Always decrements pendingSearches, even on error (tags will be nil).
11	func (b *RegistryBrowser) AddRegistryTags(registryURL, alias, repo string, tags []string) {
12		// Floored: a duplicate or late response would otherwise drive the counter
13		// negative, and the next search would start from that base — IsSearching()
14		// would stay false while requests were genuinely in flight, so the spinner
15		// never showed.
16		if b.pendingSearches > 0 {
17			b.pendingSearches--
18		}
19		for _, tag := range tags {
20			b.tags = append(b.tags, MultiRegistryTag{
21				RegistryURL: registryURL,
22				Alias:       alias,
23				Repo:        repo,
24				Tag:         tag,
25			})
26		}
27		if b.state == browserStateTags {
28			b.rebuildTagTable()
29		}
30	}
